def takeover(entries,supported):
    import fcntl,os,socket,stat
    if type(supported) is not int or supported!=1 or not isinstance(entries,list) or len(entries)!=2:raise ValueError('supported layout and exactly two named handles required')
    if any(not isinstance(row,dict) or row.get('layout')!=supported or type(row.get('layout')) is not int for row in entries):raise ValueError('incompatible application layout')
    names=[row.get('name') for row in entries];fds=[row.get('fd') for row in entries]
    if set(names)!={'state','listener'} or len(set(names))!=2 or any(type(fd) is not int or fd<3 for fd in fds) or len(set(fds))!=2:raise ValueError('missing or duplicate handle')
    result={}
    for row in entries:
        fd=row['fd'];info=os.fstat(fd)
        if info.st_dev!=row['dev'] or info.st_ino!=row['ino']:raise ValueError('retained resource identity changed')
        if row['name']=='state':
            if not stat.S_ISREG(info.st_mode) or fcntl.fcntl(fd,fcntl.F_GETFL)&os.O_ACCMODE!=os.O_RDONLY or os.lseek(fd,0,os.SEEK_CUR)!=row['offset']:raise ValueError('state mode or shared offset changed')
        else:
            if not stat.S_ISSOCK(info.st_mode):raise ValueError('listener is not a socket')
            with socket.socket(fileno=os.dup(fd)) as listener:
                if listener.getsockopt(socket.SOL_SOCKET,socket.SO_TYPE)!=socket.SOCK_STREAM or not listener.getsockopt(socket.SOL_SOCKET,socket.SO_ACCEPTCONN) or list(listener.getsockname())!=row['address']:raise ValueError('listener binding changed')
        result[row['name']]=fd
    return result
```

原题知识说明：
交付被保存fd的类型、命名、数量上限和新进程接收合同。使用systemd支持的fd store能力前，必须由开发制品明确发送及取回协议；管理器保存句柄不等于保存完整应用状态。验收重启后套接字或文件身份、偏移与访问模式一致，同时覆盖未提供fd、重复名称和版本布局变化。存储上限与泄漏监控需记录，不能用无限句柄保持一切资源。若新版本无法解释继承资源，应停止切换并由旧兼容版本接管或按受控流程关闭重建，不能随意把未知fd当标准输入使用。

